const summarize=(text:string)=>{const clean=(text.match(/[^.!?\n]+[.!?]?/g)||[]).map(s=>s.replace(/^\s*(speaker\s*\d+|[A-Z][a-z]+):\s*/i,'').trim()).filter(s=>s.length>2);if(!clean.length)return{summary:'No transcript is available yet.',actions:[]};const stop=new Set('the a an and or but to of in on for with is are was were be been it this that we i you they he she our your their from at as by about so just really have has had do did can could would'.split(' '));const freq=new Map<string,number>();clean.join(' ').toLowerCase().match(/[a-z][a-z\x27-]{2,}/g)?.forEach(w=>{if(!stop.has(w))freq.set(w,(freq.get(w)||0)+1)});const topics=[...freq.entries()].sort((a,b)=>b[1]-a[1]).slice(0,4).map(([w])=>w);const actionPattern=/\b(?:i|we|you|they|he|she|[A-Z][a-z]+)\s+(?:will|need(?:s)? to|should|must|plan(?:s)? to|agreed to|is going to|are going to)\b|^(?:please\s+)?(?:send|review|complete|schedule|confirm|check|update|create|prepare|call|email|share|follow up|finish|submit|assign|contact)\b|\b(?:due|deadline|by (?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|tomorrow|next week|\w+ \d{1,2}))\b/i;const decisionPattern=/\b(decided|agreed|approved|selected|confirmed|finalized|will proceed|moving forward)\b/i;const actions=clean.filter(s=>actionPattern.test(s)).slice(0,8);const decisions=clean.filter(s=>decisionPattern.test(s)).slice(0,4);const scored=clean.map((s,i)=>({s,i,score:(s.toLowerCase().match(/[a-z][a-z\x27-]{2,}/g)||[]).reduce((n,w)=>n+(freq.get(w)||0),0)/Math.max(5,s.split(/\s+/).length)})).filter(x=>!actions.includes(x.s)).sort((a,b)=>b.score-a.score||a.i-b.i).slice(0,3).sort((a,b)=>a.i-b.i).map(x=>x.s);const parts=[`Overview: The meeting focused on ${topics.length?topics.join(', '):'the topics captured in the transcript'}.`,scored.length?`Key points:\n${scored.map(s=>'• '+s).join('\n')}`:'',decisions.length?`Decisions:\n${decisions.map(s=>'• '+s).join('\n')}`:'No explicit decisions were identified.',actions.length?`Follow-up: ${actions.length} action item${actions.length===1?'':'s'} identified.`:'No explicit follow-up assignments were identified.'];return{summary:parts.filter(Boolean).join('\n\n'),actions}};
