 const panel=useRef<HTMLDivElement|null>(null);
 useEffect(()=>{if(!open)return;const previous=document.activeElement as HTMLElement|null;panel.current?.focus();const key=(event:KeyboardEvent)=>{if(event.key==='Escape')onClose()};document.addEventListener('keydown',key);document.body.classList.add('settings-visible');return()=>{document.removeEventListener('keydown',key);document.body.classList.remove('settings-visible');previous?.focus()}},[open,onClose]);
